import java.util.Arrays;

public class Ex01ArrayList {
    // 复刻 JDK ArrayList 的扩容策略：
    //   首次 add 惰性初始化为默认容量 10；
    //   之后每次扩容为 oldCapacity + (oldCapacity >> 1)，即 1.5 倍。
    //   （JDK 9+ 模块化后无法再反射访问 java.util 的内部字段 elementData）
    static class MiniArrayList<E> {
        private static final Object[] EMPTY = {};
        private Object[] elementData = EMPTY;
        private int size;

        int size() { return size; }
        int capacity() { return elementData.length; }

        private Object[] grow(int minCapacity) {
            int oldCapacity = elementData.length;
            if (oldCapacity > 0) {
                int newCapacity = oldCapacity + (oldCapacity >> 1);
                if (newCapacity < minCapacity) newCapacity = minCapacity;
                return Arrays.copyOf(elementData, newCapacity);
            }
            return new Object[Math.max(10, minCapacity)];
        }

        void add(E e) {
            if (size == elementData.length) elementData = grow(size + 1);
            elementData[size++] = e;
        }

        @SuppressWarnings("unchecked")
        E get(int i) { return (E) elementData[i]; }
    }

    public static void main(String[] args) {
        MiniArrayList<Integer> list = new MiniArrayList<>();
        System.out.println("initial size=" + list.size() + " capacity=" + list.capacity());
        for (int i = 1; i <= 11; i++) list.add(i);
        System.out.println("after 11 adds size=" + list.size() + " capacity=" + list.capacity());
        System.out.println("get(5)=" + list.get(5));
    }
}
